package com.bank.portable;

import java.math.BigDecimal;
import java.util.logging.*;

public class PortabilityDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        StatementService service = new StatementService();

        String statement = service.formatStatement(rajesh);
        log.info(() -> "Running on OS: " + System.getProperty("os.name"));
        log.info(() -> "Statement (identical bytecode output on every OS):\n" + statement);
    }
}

