class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be StatementService.java in a real project ───
class StatementService {
    // Uses platform-NEUTRAL APIs so output logic is the same everywhere.
    String formatStatement(Account acc) {
        String nl = System.lineSeparator(); // portable line ending
        StringBuilder sb = new StringBuilder();
        sb.append("National Bank of India - Mini Statement").append(nl);
        sb.append("Account : ").append(acc.getAccountId()).append(nl);
        sb.append("Holder  : ").append(acc.getHolderName()).append(nl);
        sb.append("Balance : Rs.").append(acc.getBalance()).append(nl);
        return sb.toString();
    }
}
